    "components": [
      {
        "name": "L2ノルム重要度",
        "description": "キー埋め込み単体のL2ノルムをKV重要度の代理指標とし、低ノルムほど保持する。問い合わせや注意行列を必要としない。"
      },
      {
        "name": "層選択圧縮",
        "description": "L2ノルムと注意重みの相関が弱い初期層を圧縮対象外にし、層ごとの経験的差を吸収する。"
      },
      {
        "name": "容量制約付き追い出し",
        "description": "所定のKV予算を超えたとき高L2ノルムのKVペアを削除し、同じトークン位置のkey/valueを一体で管理する。"
      }
    ],
    "system_design": "通常の自己回帰推論で生成されたKVをキャッシュし、keyのL2ノルムを付随統計として保持する。容量上限に達した時点でノルム順位に基づき高ノルムKVを除去する。注意スコアを外部へ取り出さないためFlashAttentionのI/O効率化を維持でき、モデル重みの変更や再学習も不要である。"
  }
}

